mapper.select:
SELECT id, account_id, user_id, operation_type, change_tokens, before_total, after_total,
       before_remaining, after_remaining, operator_id, reason, create_dept, create_by,
       create_time, update_by, update_time
FROM token_quota_log
WHERE user_id IN

    #{userId}


    AND operation_type = #{query.operationType}


    AND operator_id = #{query.operatorId}


    AND create_time >= #{query.beginTime}


    AND create_time <= #{query.endTime}

ORDER BY create_time DESC, id DESC
